input.sparql:
SELECT ?zone ?sensor ?ts WHERE {
  ?sensor a brick:AirTemperatureSensor ;
          brick:hasInputChannel ?zone .
  ?sensor ref:hasExternalReference ?tsid .
  ?ts ref:hasTimeseriesId ?tsid .
}

SELECT ?z WHERE {
  ?z a/rdfs:subClassOf* brick:Zone .
  FILTER(str(?z) LIKE '%Zone_F1_Z01%' )
}

SELECT DISTINCT ?z ?name WHERE {
  ?z rdfs:label ?name .
  FILTER(str(?name) LIKE "Zone%")
}  LIMIT 30
